const RED = [["chest_pain", "shortness_of_breath"], ["sudden_severe_headache", "vision_loss"], ["severe_bleeding"], ["difficulty_breathing", "swelling_face"], ["slurred_speech", "facial_drooping"], ["fever", "stiff_neck", "confusion"], ["coughing_blood"], ["sudden_numbness", "weakness_one_side"], ["stridor"], ["seizures"]];
const symptoms = (query.symptoms || []).map(s => String(s).toLowerCase().trim().replace(/[\s-]+/g, '_'));
const age = Number(query.age), dur = Number(query.duration_days);
const set = new Set(symptoms);
const hit = RED.find(c => c.every(s => set.has(s)));
if (hit) return JSON.stringify({ severity: 'EMERGENCY', score: 100, reason: 'Critical red-flag combination detected: ' + hit.join(', ') });
let score = symptoms.length * 2;
if (age < 2 || age > 65) score += 5; else if (age > 50) score += 2;
if (dur > 14) score += 3; else if (dur > 7) score += 1;
let severity = 'LOW', reason = 'Low risk score (' + score + '). Routine care recommended.';
if (score >= 15) { severity = 'HIGH'; reason = 'High risk score (' + score + ') based on age, duration, and symptom count.'; }
else if (score >= 8) { severity = 'MODERATE'; reason = 'Moderate risk score (' + score + ').'; }
return JSON.stringify({ severity, score, reason });

